#!/usr/bin/env python3
import base64, gzip, pathlib, subprocess, sys

EXPECTED_BEFORE = "44798a17c1dea77235f759ddb38c4ef33707d519d2f9c24d3e2cf14620050601"
EXPECTED_AFTER = "60a0c496172e4084a49774e572b6fe9a2bee68a0ee9112cf6f07a8f89284c22a"
PATCH_B64 = """"""

src = pathlib.Path(sys.argv[1]).resolve()
import hashlib
def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()
if sha(src) != EXPECTED_BEFORE:
    raise SystemExit(f"Unexpected source before patch: {sha(src)}")
patch = gzip.decompress(base64.b64decode(PATCH_B64))
proc = subprocess.run(
    ["patch", "-p0"],
    input=patch,
    cwd=src.parent,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
)
print(proc.stdout.decode("utf-8", errors="replace"))
if proc.returncode != 0:
    raise SystemExit(proc.returncode)
if sha(src) != EXPECTED_AFTER:
    raise SystemExit(f"Unexpected source after patch: {sha(src)}")
print("Patched source SHA-256:", sha(src))
